// The app-wide "console pumps", extracted from ConsoleWorkspace (console-page-is-legacy refactor,
// epic-command-surfaces-are-nodes). These drive concerns that are APP-WIDE but were mounted from the
// (always-mounted) console workspace: the shared pane-activity read, fleet coordination + the launch
// gate, runtime fault triage, kit-change dispatch, the studio-network fulfiller, the idle reaper, and
// the CI watcher. Extracted so the console page can slim to tabs + a terminal without dropping them;
// mount once from a component that stays mounted across every screen (ConsoleWorkspace).
//
// FUTURE (maintainer): each is a candidate to become its own finer-grained record, and several are
// polls whose logic belongs in Rust (fault-triage, ci-watcher; the idle reaper's DECISION already
// lives in src-tauri/src/console/pty/reap.rs — this side only reports config). Migrate per-method as
// the graph migration resumes.
//
// NOT included: useDirectorPump — it reads the console's pane-status ref and is inert since
// #app-stops-pushing-prompts, so it stays in the page until the grid is torn out.
import { useCoordinator } from "@/app/console/useCoordinator";
import { useFleetGate } from "@/shared/lib/fleet/useFleetGate";
import { useFaultTriage } from "@/app/console/useFaultTriage";
import { useKitDispatch } from "@/app/console/useKitDispatch";
import { useStudioNetworkPump } from "@/app/console/useStudioNetworkPump";
import { useIdleReaper } from "@/app/console/lib/useIdleReaper";
import { useCiWatcher } from "@/shared/lib/github/useCiWatcher";
import { usePaneActivityFeed } from "@/app/console/lib/usePaneActivityFeed";
import { resumeProjectFleet } from "@/features/glance";

/** Mount every app-wide pump the console workspace hosts. Call once from a component that stays
 *  mounted across screens (ConsoleWorkspace), so the fleet keeps advancing off-screen. */
export function useConsolePumps(): void {
  usePaneActivityFeed();
  useCoordinator();
  useFleetGate((projectKey: string) => resumeProjectFleet({ projectName: projectKey, projectKey }));
  useFaultTriage();
  useKitDispatch();
  useStudioNetworkPump();
  useIdleReaper();
  useCiWatcher();
}
